// ── Logo yükle (tek tanım, tüm img[data-logo] elementlerine ata) ──
(function(){
  var SRC = "data:image/png;base64,";
  function applyLogos(){
    document.querySelectorAll('img[data-logo]').forEach(function(img){
      img.src = SRC;
    });
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', applyLogos);
  } else {
    applyLogos();
  }
})();

// ── Galeri verileri ──
var GALLERY = [
  {title:'Çatı Kaplama',        icon:'🏗️', count:6},
  {title:'Demir Doğrama',       icon:'🚪',  count:6},
  {title:'Çelik Yapı',          icon:'🏢',  count:6},
  {title:'Garaj Kapısı',        icon:'🚗',  count:6},
  {title:'Alüminyum Kompozit',  icon:'🏛️',  count:6},
  {title:'Özel Metal İmalat',   icon:'⚙️',  count:6}
];

function openGal(i){
  var d = GALLERY[i];
  document.getElementById('gmod-title').textContent = d.title;
  var grid = document.getElementById('ggrid');
  grid.innerHTML = '';
  for(var n=0;n<d.count;n++){
    var slot = document.createElement('div');
    slot.className = 'gslot';
    slot.innerHTML = '<span class="gslot-n">0'+(n+1)+'</span>'
      +'<span class="gslot-ico">'+d.icon+'</span>'
      +'<span class="gslot-lbl">Fotoğraf Eklenecek</span>';
    grid.appendChild(slot);
  }
  var modal = document.getElementById('gmodal');
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
  document.addEventListener('keydown', escHandler);
}

function closeGal(){
  document.getElementById('gmodal').style.display = 'none';
  document.body.style.overflow = '';
  document.removeEventListener('keydown', escHandler);
}

function escHandler(e){ if(e.key==='Escape') closeGal(); }

// ── Nav scroll ──
var nav = document.getElementById('nav');
var stb = document.getElementById('stb');

window.addEventListener('scroll', function(){
  var y = window.scrollY;
  nav.classList.toggle('sc', y > 40);
  stb.classList.toggle('vis', y > 400);
}, {passive:true});

// ── Mobil menü ──
var hb  = document.getElementById('hbtn');
var dr  = document.getElementById('drw');

hb.addEventListener('click', function(){
  var o = dr.classList.toggle('op');
  hb.classList.toggle('op', o);
  hb.setAttribute('aria-expanded', String(o));
  document.body.style.overflow = o ? 'hidden' : '';
});

dr.querySelectorAll('a').forEach(function(a){
  a.addEventListener('click', function(){
    dr.classList.remove('op');
    hb.classList.remove('op');
    hb.setAttribute('aria-expanded','false');
    document.body.style.overflow = '';
  });
});

// ── Keyboard: hizmet kartlarında Enter/Space ──
document.querySelectorAll('.svc[tabindex]').forEach(function(el){
  el.addEventListener('keydown', function(e){
    if(e.key==='Enter'||e.key===' '){ e.preventDefault(); el.click(); }
  });
});

// ── Sayaç animasyonu ──
var counted = false;
var cnts = document.querySelectorAll('.cnt');
if(cnts.length && 'IntersectionObserver' in window){
  var cntIO = new IntersectionObserver(function(entries){
    if(entries[0].isIntersecting && !counted){
      counted = true;
      cnts.forEach(function(el){
        var target = +el.dataset.t;
        var step   = target / (1800/16);
        var cur    = 0;
        var id = setInterval(function(){
          cur = Math.min(cur+step, target);
          el.textContent = Math.floor(cur);
          if(cur>=target) clearInterval(id);
        }, 16);
      });
    }
  },{threshold:.5});
  var statsEl = document.querySelector('.stats');
  if(statsEl) cntIO.observe(statsEl);
}

// ── Smooth scroll (nav offset 75px) ──
document.querySelectorAll('a[href^="#"]').forEach(function(a){
  a.addEventListener('click', function(e){
    var id = a.getAttribute('href');
    if(id==='#') return;
    var target = document.querySelector(id);
    if(target){
      e.preventDefault();
      window.scrollTo({
        top: target.getBoundingClientRect().top + window.scrollY - 75,
        behavior:'smooth'
      });
    }
  });
});

// ── Form gönder ──
function doSubmit(){
  var n = document.getElementById('fn').value.trim();
  var p = document.getElementById('fp').value.trim();
  if(!n||!p){ alert('Lütfen ad soyad ve telefon numaranızı girin.'); return; }
  document.getElementById('fBody').style.display='none';
  document.getElementById('fOk').style.display='block';
}
